// Filter out already-processed docs (dedup)
const docsResponse = $('List Docs In Folder').first().json;
const processedIds = $('Get Already Processed IDs').first().json;

const allDocs = docsResponse.files || [];
const processedSet = new Set(Array.isArray(processedIds) ? processedIds : []);

// Filter: only new docs, and only Google Docs or text files
const newDocs = allDocs.filter(doc => {
  // Check if any product from this doc has been processed
  // processedIds are in format 'docId__productName', so check prefix
  const isProcessed = Array.from(processedSet).some(id => id.startsWith(doc.id + '__'));
  if (isProcessed) return false;
  // Accept Google Docs and plain text
  const validTypes = ['application/vnd.google-apps.document', 'text/plain', 'application/pdf'];
  return !doc.mimeType || validTypes.includes(doc.mimeType);
});

if (newDocs.length === 0) {
  return [{ json: { _skip: true, message: 'No new documents to process' } }];
}

return newDocs.map(doc => ({ json: doc }));

// Extract plain text from Google Doc body content
const doc = $input.item.json;
const docMeta = $('Has New Docs?').item.json;

let text = '';
if (doc.body && doc.body.content) {
  for (const element of doc.body.content) {
    if (element.paragraph) {
      for (const el of element.paragraph.elements || []) {
        if (el.textRun) text += el.textRun.content;
      }
    }
  }
}

return [{
  json: {
    docText: text.trim().slice(0, 12000),
    docId: docMeta.id,
    docTitle: docMeta.name,
    docUrl: docMeta.webViewLink || `https://docs.google.com/document/d/${docMeta.id}`,
  }
}];

