const geminiText = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const prev = $('Extract Text From Doc').item.json;

let parsed = { products: [], summary: '' };
try {
  // Handle potential markdown code fences
  let cleaned = geminiText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : cleaned);
} catch(e) {
  // Fallback: treat the whole doc as one product
  parsed = {
    products: [{
      productName: prev.docTitle,
      mentionContext: 'Full document — could not parse individual products',
      assessment: 'watch',
      reasoning: 'AI extraction failed, needs manual review',
      confidence: 0.3,
    }],
    summary: '1 product (fallback extraction)',
  };
}

// Ensure products is an array
if (!Array.isArray(parsed.products)) parsed.products = [];

return [{
  json: {
    docId: prev.docId,
    docTitle: prev.docTitle,
    docUrl: prev.docUrl,
    products: parsed.products,
    summary: parsed.summary || `${parsed.products.length} products extracted`,
  }
}];
